local Profiles=include("rhenium_loadout_profiles/profiles.lua");local Names={HookPrefix="rhenium_loadout_profiles"};local Server={};local core,bindings,installed=nil,{},false;local function valid(p)return IsValid(p)and p:IsPlayer()end;local function logical(p)for _,r in ipairs(bindings)do if r.object==p then return r.id end end end
function Server.Install(o)if installed then return Server end;o=o or{};core=assert(Profiles.new({state=o.state}));hook.Add("PlayerSpawn",Names.HookPrefix..".PlayerSpawn",function(p)timer.Simple(0,function()if logical(p)then Server.Apply(p)end end)end);hook.Add("PlayerDisconnected",Names.HookPrefix..".PlayerDisconnected",function(p)local id=logical(p);if id then core:disconnect(id,CurTime())end;for i=#bindings,1,-1 do if bindings[i].object==p then table.remove(bindings,i)end end end);installed=true;return Server end
function Server.BindPlayer(p,id)if not installed or not valid(p)or type(id)~="string"then return false end;bindings[#bindings+1]={object=p,id=id};return true end
function Server.HandlePut(p,r,n,s,rev)local id=logical(p);if not id then return false,"unbound",{}end;return core:put(r,id,n,s,rev)end
function Server.HandleSelect(p,r,n,rev)local id=logical(p);if not id then return false,"unbound",{}end;return core:select(r,id,n,rev)end
function Server.Apply(p)local id=logical(p);if not valid(p)or not id then return false,"unbound",{}end;local plan,e=core:plan(id);if not plan then return false,e,{}end;if not pcall(function()p:StripWeapons();p:RemoveAllAmmo()end)then return false,"strip_failed",{}end;local given={};for _,w in ipairs(plan.weapons)do local ok,v=pcall(function()return p:Give(w.class,true)end);if not ok or not IsValid(v)then return false,"give_failed",{given=given}end;given[#given+1]=w.class end;for _,a in ipairs(plan.ammo)do if not pcall(function()p:GiveAmmo(a.amount,a.type,true)end)then return false,"ammo_failed",{given=given}end end;if given[1]then p:SelectWeapon(given[1])end;return true,"applied",{weapons=given,ammo=plan.ammo}end
function Server.Save()return core and core:save(CurTime())end;function Server.Shutdown()if installed then for _,x in ipairs({{"PlayerSpawn",".PlayerSpawn"},{"PlayerDisconnected",".PlayerDisconnected"}})do hook.Remove(x[1],Names.HookPrefix..x[2])end;installed=false end;if core then core:shutdown()end;bindings={};return true,"shutdown"end;return Server
